import {recordAnswer} from './model.js';
import {defaultLearning,studyCollection,studyGrammar,wordTopics,sentenceScenes} from './study-data.js';
import {genkiLessons,genkiSources,defaultGenki,genkiConfig,getGenkiLesson,createGenkiSession,genkiQuestion,genkiScope,markGenkiLesson} from './genki-data.js';

export {defaultGenki} from './genki-data.js';
export function createGenkiFeature({getState,commit,ui,toast=()=>{},isBusy=()=>false,navigate=()=>{},onQuestionStart=()=>{}}={}){
 let startedAt=performance.now();
 const U=()=>typeof ui==='function'?ui():ui;
 const config=()=>genkiConfig(getState().genki);
 const focus=()=>{globalThis.document?.querySelector('#genki-stage-title')?.focus({preventScroll:true});globalThis.document?.querySelector('.genki-session,.genki-detail')?.scrollIntoView({block:'start'});};
 const begin=()=>{startedAt=performance.now();const session=config().session;onQuestionStart(genkiQuestion(session),genkiScope(session));focus();};
 const wordCount=(state,tag)=>(state.personal?.words||[]).filter(word=>!word.deletedAt&&Array.isArray(word.tags)&&word.tags.some(value=>String(value).toLocaleLowerCase('en')===tag)).length;
 function page(){
  const state=getState(),g=config(),lesson=getGenkiLesson(g.selectedLesson),{T,L,esc}=U(),session=g.session;
  const heading=`<div class="page-heading"><p class="eyebrow">${T('KİTABININ YANINDA','ALONGSIDE YOUR BOOK')}</p><h1 tabindex="-1">${T('Genki çalışma yolu','Genki study path')}</h1><p class="muted">${T('GENKI I · 1–12 ve GENKI II · 13–23. 3. baskının ders sırasına göre hazırlanmış özgün kısa tekrarlar.','GENKI I · 1–12 and GENKI II · 13–23. Original short reviews following the 3rd-edition lesson order.')}</p></div>`;
  if(session?.phase==='exercise'){
   const q=genkiQuestion(session),event=state.events.find(event=>event.id===session.feedback);
   if(!q)return `${heading}<section class="panel genki-session"><h2 id="genki-stage-title" tabindex="-1">${T('Bu tur yüklenemedi.','This round could not load.')}</h2><p>${T('Ders rehberine dönüp yeni bir tur açabilirsin. Cevap kaydedilmedi.','Return to the guide and start a new round. No answer was recorded.')}</p><button class="btn secondary" data-action="genki-close">${T('Rehbere dön','Back to guide')}</button></section>`;
   return `${heading}<section class="genki-session"><div class="section-top"><h2 id="genki-stage-title" tabindex="-1">${T('Ders','Lesson')} ${session.lessonNumber} · ${T('Özgün mini pratik','Original mini practice')}</h2><button class="subtle-link" data-action="genki-close">${T('Rehbere dön','Back to guide')}</button></div><p class="genki-small">${T('Bu soru başladığın haliyle korunur. Yalnızca gönderdiğin cevap tekrar planına kaydedilir.','This question keeps its starting snapshot. Only a submitted answer enters your review schedule.')}</p><section class="exercise-card genki-exercise"><span class="level-pill">${T('Yazılı cevap · 1 soru','Written answer · 1 question')}</span><h3 id="genki-answer-prompt">${esc(L(q.prompt))}</h3><p class="genki-question-text" lang="ja">${esc(q.context)}</p>${!event?`<div class="genki-reading-tools"><button type="button" class="reading-hint-button" data-action="genki-toggle-reading" aria-pressed="${!!session.showReading}" aria-controls="genki-context-reading">${session.showReading?T('Okunuşu gizle','Hide reading'):T('Okunuşu göster','Show reading')}</button><p class="genki-reading" id="genki-context-reading" lang="ja" ${session.showReading?'':'hidden'}>${esc(q.contextReading)}</p></div>`:''}<form data-form="genki-answer" data-session-id="${esc(session.id)}" data-question-id="${esc(q.id)}" aria-labelledby="genki-answer-prompt"><label class="answer-label" for="genki-answer-input">${T('Eksik kısmı Japonca yaz','Type the missing part in Japanese')}</label><input class="answer-input" id="genki-answer-input" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="200" required ${event?'disabled':''} value="${esc(event?.answer||'')}">${!event?`<button class="btn primary full-width" type="submit">${T('Kontrol et','Check answer')}</button>`:''}</form>${event?`<div class="feedback ${event.correct?'correct':'incorrect'}" tabindex="-1" role="status"><strong>${event.correct?T('Doğru.','Correct.'):T('Birlikte gözden geçirelim.','Let’s review it together.')}</strong><p>${esc(L(q.explanation))}</p><p>${T('Kabul edilen','Accepted')}: <strong lang="ja">${esc(L(q.answers).join(' / '))}</strong></p><p class="genki-reading" lang="ja">${esc(q.contextReading)}</p>${event.readingHintShown?`<p class="genki-small">${T('Cevaplamadan önce okunuş ipucu açıldı.','The reading hint was shown before answering.')}</p>`:''}</div><button class="btn primary full-width" data-action="genki-next">${T('Turu bitir','Finish round')}</button>`:''}</section></section>`;
  }
  if(session?.phase==='done'){
   const events=state.events.filter(event=>session.eventIds?.includes(event.id)),completed=!!g.completedLessons[session.lessonNumber];
   return `${heading}<section class="panel genki-session genki-done"><p class="eyebrow">${T('KÜÇÜK BİR TEKRAR','A LITTLE REVIEW')}</p><h2 id="genki-stage-title" tabindex="-1">${T('Mini pratik tamam.','Mini practice complete.')}</h2><p>${T(`${events.length} cevap · ${events.filter(event=>event.correct).length} doğru.`,`${events.length} ${events.length===1?'answer':'answers'} · ${events.filter(event=>event.correct).length} correct.`)}</p><p class="genki-small">${T('Bu sonuç, kitabın bütün dersini bildiğini göstermez. Dersin tamamlanma işaretini kendin seçersin.','This result does not establish knowledge of the whole book lesson. You choose the lesson completion mark yourself.')}</p><div class="genki-actions"><button class="btn primary" data-action="genki-close">${T('Ders rehberine dön','Back to lesson guide')}</button><button class="btn secondary" data-action="genki-complete" data-lesson="${session.lessonNumber}" aria-pressed="${completed}">${completed?T('İşaretini kaldır','Remove your mark'):T('Dersi tamamlandı işaretle','Mark lesson complete')}</button></div></section>`;
  }
  const visible=genkiLessons.filter(item=>g.book==='all'||item.book===Number(g.book)),completed=!!g.completedLessons[lesson.number],total=Object.keys(g.completedLessons).length;
  const sidebar=`<aside class="genki-outline"><label class="genki-book-filter" for="genki-book"><span>${T('Kitap seç','Choose a book')}</span><select id="genki-book" data-genki-filter="book"><option value="all" ${g.book==='all'?'selected':''}>${T('İki kitap · 23 ders','Both books · 23 lessons')}</option><option value="1" ${g.book==='1'?'selected':''}>GENKI I · 1–12</option><option value="2" ${g.book==='2'?'selected':''}>GENKI II · 13–23</option></select></label><div class="genki-outline-heading"><h2>${T('Dersler','Lessons')}</h2><span>${total} / 23</span></div><p class="genki-small">${T('Sayı, senin tamamlandı işaretlerini gösterir.','The count shows your own completion marks.')}</p><div class="genki-lesson-list" data-scroll-key="genki-lessons" role="list" aria-label="${T('Genki dersleri','Genki lessons')}">${visible.map(item=>`<div role="listitem"><button class="genki-lesson-choice" data-action="genki-select" data-lesson="${item.number}" ${item.number===lesson.number?'aria-current="step"':''}><span class="genki-lesson-number">${item.number}</span><span><strong>${esc(L(item.theme))}</strong><small>GENKI ${item.book===1?'I':'II'}${g.completedLessons[item.number]?` · ${T('İşaretledin','Marked complete')}`:''}</small></span><span class="genki-lesson-check" aria-hidden="true">${g.completedLessons[item.number]?'✓':'·'}</span></button></div>`).join('')}</div></aside>`;
  const grammar=studyGrammar.find(item=>item.id===lesson.related.grammarId),topic=wordTopics.find(item=>item.id===lesson.related.wordTopic),scene=sentenceScenes.find(item=>item.id===lesson.related.scene),count=wordCount(state,lesson.tag);
  const detail=`<article class="genki-detail" aria-labelledby="genki-stage-title"><div class="genki-detail-header"><span class="level-pill">GENKI ${lesson.book===1?'I':'II'} · ${T('3. baskı','3rd edition')} · ${T('Ders','Lesson')} ${lesson.number}</span><h2 id="genki-stage-title" tabindex="-1">${esc(L(lesson.theme))}</h2><p>${esc(L(lesson.goals))}</p></div><section class="genki-focus"><h3>${T('Seçilmiş gramer odağı','Selected grammar focus')}</h3><p class="genki-pattern" lang="ja">${esc(lesson.focus)}</p><p>${esc(L(lesson.explanation))}</p><div class="genki-example"><span class="genki-label">${T('Yomu’nun özgün örneği','Yomu’s original example')}</span><p lang="ja">${esc(lesson.example.ja)}</p><p class="genki-reading" lang="ja">${esc(lesson.example.reading)}</p><p>${esc(L(lesson.example.translation))}</p></div></section><section class="genki-practice-launch"><div><h3>${T('Küçük bir kontrol','A small check')}</h3><p>${T('Bu odağa ait 1 özgün boşluk doldurma sorusu.','1 original gap-fill question for this focus.')}</p></div><button class="btn primary" data-action="genki-start" data-lesson="${lesson.number}">${T('Mini pratiği aç','Start mini practice')}</button></section><section class="genki-related"><h3>${T('Yomu’da pekiştir','Reinforce it in Yomu')}</h3><p class="genki-small">${T('Bunlar kitabın alıştırmaları değildir. Yomu’daki ilgili içerik seçkilerini açar.','These are not book exercises. They open related Yomu content selections.')}</p><div class="genki-related-links">${grammar?`<button data-action="genki-related" data-kind="grammar" data-lesson="${lesson.number}"><span>${T('Gramer tekrarı','Grammar review')}</span><strong>${esc(L(grammar.title))}</strong><small lang="ja">${esc(grammar.form)}</small></button>`:''}<button data-action="genki-related" data-kind="vocabulary" data-lesson="${lesson.number}"><span>${T('Kelime seçkisi','Vocabulary selection')}</span><strong>${esc(topic?.[state.settings.language]||lesson.related.wordTopic)}</strong></button><button data-action="genki-related" data-kind="sentences" data-lesson="${lesson.number}"><span>${T('Cümle pratiği','Sentence practice')}</span><strong>${esc(scene?.[state.settings.language]||lesson.related.scene)}</strong></button></div></section><section class="genki-personal"><h3>${T('Kitabından kendi kelimelerin','Your own words from your book')}</h3><p>${T('Destelerim’de kendi eklediğin kelimelere bu etiketi yaz. Sonra bu dersin kelimelerini birlikte açabilirsin.','Add this tag to words you enter in My decks. Then open your words for this lesson together.')}</p><div class="genki-tag-row"><code>${esc(lesson.tag)}</code><span>${count} ${T('etiketli kelime',count===1?'tagged word':'tagged words')}</span></div><button class="btn secondary" data-action="genki-personal" data-lesson="${lesson.number}">${count?T('Etiketli kelimelerimi aç','Open my tagged words'):T('Destelerimde bu etiketi aç','Open this tag in My decks')}</button></section><footer class="genki-completion"><button class="genki-completion-toggle" data-action="genki-complete" data-lesson="${lesson.number}" aria-pressed="${completed}"><span aria-hidden="true">${completed?'✓':'○'}</span><span>${completed?T('Bu dersi tamamlandı işaretledin','You marked this lesson complete'):T('Bu dersi tamamlandı işaretle','Mark this lesson complete')}</span></button><p>${T('Bu işaret senin çalışma kaydındır; dil yeterliği, kitap sınavı veya JLPT sonucu değildir.','This is your study mark; it is not language proficiency, a book test or a JLPT result.')}</p></footer><div class="genki-step-links">${lesson.number>1?`<button class="subtle-link" data-action="genki-select" data-lesson="${lesson.number-1}">← ${T('Önceki ders','Previous lesson')}</button>`:''}${lesson.number<23?`<button class="subtle-link" data-action="genki-select" data-lesson="${lesson.number+1}">${T('Sonraki ders','Next lesson')} →</button>`:''}</div></article>`;
  return `${heading}<section class="genki-intro"><p>${T('Kitabını sırayla çalışırken burada kaldığın dersi seç. Rehberdeki temalar ve seçilmiş odaklar kısa bir eşlikçidir; kitabın bütün içeriğini kapsamaz.','Select your current lesson as you work through your book. These themes and selected focus points are a short companion and do not cover the whole book.')}</p><details data-disclosure-key="genki-sources"><summary>${T('Baskı, kaynak ve kapsam','Edition, sources and scope')}</summary><p>${T('Ders eşleştirmesi yayıncının 3. baskı planıyla doğrulandı. Açıklamalar, örnekler ve mini sorular Yomu için özgün hazırlanmıştır; kitap sayfaları, kelime listeleri ve sesleri aktarılmaz.','Lesson mapping was checked against the publisher’s 3rd-edition plan. Notes, examples and mini questions are original to Yomu; book pages, vocabulary lists and audio are not reproduced.')}</p><a href="${genkiSources.structure}" target="_blank" rel="noopener noreferrer">${T('Yayıncının kitap yapısı','Publisher’s book structure')} ↗</a><a href="${genkiSources.syllabus}" target="_blank" rel="noopener noreferrer">${T('Resmî 3. baskı ders planı (PDF)','Official 3rd-edition syllabus (PDF)')} ↗</a></details></section><div class="genki-layout">${sidebar}${detail}</div>`;
 }
 async function click(target){
  const action=target?.dataset?.action;if(!['genki-select','genki-start','genki-close','genki-next','genki-complete','genki-toggle-reading','genki-personal','genki-related'].includes(action))return false;if(isBusy())return true;
  const state=getState(),g=genkiConfig(state.genki),{T}=U(),lesson=getGenkiLesson(target.dataset.lesson||g.selectedLesson);
  if(action==='genki-close'){const next=structuredClone(state);next.genki={...g,session:null};if(await commit(next))focus();return true;}
  if(action==='genki-next'){
   if(g.session?.phase!=='exercise'||!g.session.feedback)return true;const next=structuredClone(state);next.genki={...g,session:{...g.session,index:1,feedback:null,phase:'done'}};if(await commit(next))focus();return true;
  }
  if(action==='genki-toggle-reading'){
   const q=genkiQuestion(g.session);if(!q||g.session.feedback)return true;const next=structuredClone(state);next.genki={...g,session:{...g.session,showReading:!g.session.showReading,readingHintIds:[...new Set([...(g.session.readingHintIds||[]),q.id])]}};await commit(next);return true;
  }
  if(!lesson)return true;
  if(action==='genki-complete'){const complete=!g.completedLessons[lesson.number];if(await commit(markGenkiLesson(state,lesson.number,complete)))toast(complete?T('Ders, senin işaretinle tamamlandı.','Lesson marked complete by you.'):T('Tamamlandı işaretin kaldırıldı.','Your completion mark was removed.'));return true;}
  if(g.session?.phase==='exercise')return true;
  const next=structuredClone(state);next.genki={...g};
  if(action==='genki-select'){
   next.genki.selectedLesson=lesson.number;next.genki.lastOpenedAt=new Date().toISOString();next.genki.session=null;if(g.book!=='all'&&g.book!==String(lesson.book))next.genki.book=String(lesson.book);if(await commit(next))focus();
  }else if(action==='genki-start'){
   next.genki.selectedLesson=lesson.number;next.genki.session=createGenkiSession(lesson.number,{showReading:!!state.settings.questionReadings});next.genki.lastOpenedAt=new Date().toISOString();if(await commit(next))begin();
  }else if(action==='genki-personal'){
   if(!next.personal){toast(T('Kişisel desteler henüz hazır değil.','Personal decks are not ready yet.'));return true;}
   next.personal={...next.personal,selectedDeckId:'all',selectedWordId:'',search:lesson.tag,session:null};if(await commit(next))navigate('personal');
  }else if(action==='genki-related'){
   const kind=target.dataset.kind;if(!['grammar','vocabulary','sentences'].includes(kind))return true;
   const collection=studyCollection(kind),category=kind==='vocabulary'?lesson.related.wordTopic:kind==='sentences'?lesson.related.scene:'all',item=kind==='grammar'?collection.find(item=>item.id===lesson.related.grammarId):collection.find(item=>(kind==='vocabulary'?item.category:item.scene)===category);if(!item)return true;
   const defaults=defaultLearning();next.learning={...defaults,...next.learning,session:null,[kind]:{...defaults[kind],...next.learning?.[kind],level:'all',category,search:'',selectedId:item.id}};if(await commit(next))navigate(kind);
  }
  return true;
 }
 async function change(target){
  if(target?.dataset?.genkiFilter!=='book')return false;if(isBusy()||!['all','1','2'].includes(target.value))return true;const state=getState(),g=genkiConfig(state.genki);if(g.session?.phase==='exercise')return true;
  const next=structuredClone(state);next.genki={...g,book:target.value};const lesson=getGenkiLesson(g.selectedLesson);if(target.value!=='all'&&lesson.book!==Number(target.value))next.genki.selectedLesson=target.value==='1'?1:13;next.genki.lastOpenedAt=new Date().toISOString();next.genki.session=null;await commit(next);return true;
 }
 async function submit(form){
  if(form?.dataset?.form!=='genki-answer')return false;if(isBusy())return true;
  const state=getState(),g=genkiConfig(state.genki),session=g.session,q=genkiQuestion(session);if(!q||session.feedback||form.dataset.sessionId!==session.id||form.dataset.questionId!==q.id)return true;
  const answer=String(new FormData(form).get('answer')||'').trim();if(!answer||answer.length>200)return true;
  const next=recordAnswer(state,q,answer,new Date(),crypto.randomUUID(),Math.max(0,Math.min(600000,Math.round(performance.now()-startedAt))),'genki'),event=next.events.at(-1);
  event.readingHintShown=!!session.readingHintIds?.includes(q.id);event.pronunciationHintRequested=!!session.pronunciationHintIds?.includes(q.id);event.genkiLesson=session.lessonNumber;event.practiceScope=genkiScope(session);
  next.genki={...g,session:{...session,feedback:event.id,eventIds:[...session.eventIds,event.id]}};if(await commit(next))globalThis.document?.querySelector('.genki-session .feedback')?.focus({preventScroll:true});return true;
 }
 return {page,click,submit,change};
}
